class Solution {
public:
    int minKnightMoves(int x, int y) {
        x = abs(x);
        y = abs(y);
        queue<pair<int, int>> q;
        set<pair<int, int>> seen;
        q.push({0, 0});
        seen.insert({0, 0});
        int dx[8] = {1, 1, 2, 2, -1, -1, -2, -2};
        int dy[8] = {2, -2, 1, -1, 2, -2, 1, -1};
        int steps = 0;
        while (!q.empty()) {
            int count = q.size();
            while (count-- > 0) {
                auto p = q.front();
                q.pop();
                if (p.first == x && p.second == y) {
                    return steps;
                }
                for (int d = 0; d < 8; ++d) {
                    int nx = p.first + dx[d];
                    int ny = p.second + dy[d];
                    if (nx >= -2 && ny >= -2 && nx <= x + 2 && ny <= y + 2
                        && seen.insert({nx, ny}).second) {
                        q.push({nx, ny});
                    }
                }
            }
            ++steps;
        }
        return -1;
    }
};
